mapper.select:
SELECT /* LGSYSC00220.retrieveMenuListByRole */ DECODE((SELECT COUNT(1) FROM LGCOM_FULL_SYSTEM_FAVOR_HIER_N WHERE application_user_id = lu.application_user_id AND menu_id = lu.menu_id),1,'Y','N') AS user_menu_yn , application_user_id , menu_id , menu_name , system_code , module_code , high_menu_id , program_id , menu_desc , menu_level_no , sort_order_no FROM LGCOM_USER_MENU_INFO_V lu WHERE system_code = #{systemCode} AND language_code = #{USER_SESSION.languageCode} AND application_user_id = #{USER_SESSION.applicationUserId, jdbcType=NUMERIC}
AND module_code = #{moduleCode}
AND menu_id IN ( SELECT menu_id FROM LGCOM_MENU_M START WITH menu_name LIKE '%'||#{menuName}||'%' CONNECT BY PRIOR high_menu_id = menu_id)
ORDER BY menu_order_by

mapper.delete:
DELETE FROM /* LGSYSC00220.deleteUserMenu */
            LGCOM_FULL_SYSTEM_FAVOR_HIER_N
 WHERE APPLICATION_USER_ID = #{USER_SESSION.applicationUserId, jdbcType=NUMERIC}
   AND MENU_ID = #{menuId}

/*LGSYSC00220.updateUserTopMenuOrder*/
    UPDATE LGCOM_FULL_SYSTEM_FAVOR_HIER_N
       SET SORT_ORDER_NO = #{sortOrderNo}
     WHERE APPLICATION_USER_ID = #{USER_SESSION.applicationUserId, jdbcType=NUMERIC}
       AND MENU_ID = #{menuId}

mapper.insert:
	/*LGSYSC00220.insertUserMenu*/
	INSERT INTO LGCOM_FULL_SYSTEM_FAVOR_HIER_N
	   ( APPLICATION_USER_ID
	    ,MENU_ID
	    ,SORT_ORDER_NO
	    ,CREATED_BY
	    ,CREATION_DATE
	    ,LAST_UPDATED_BY
	    ,LAST_UPDATE_DATE  )
	  SELECT 
	    #{USER_SESSION.applicationUserId, jdbcType=NUMERIC}
	    ,#{menuId}
	    ,#{sortOrderNo}
	    ,#{USER_SESSION.applicationUserId, jdbcType=NUMERIC}
	    ,SYSDATE
	    ,#{USER_SESSION.applicationUserId, jdbcType=NUMERIC}
	    ,SYSDATE  
	  FROM DUAL
	 WHERE not exists (SELECT '1' 
	                   FROM lgcom_full_system_favor_hier_n t
                      WHERE t.menu_id = #{menuId}
                        AND t.application_user_id = #{USER_SESSION.applicationUserId, jdbcType=NUMERIC})
